mapper.select:
SELECT id, account_id, role_code, role_name, role_desc, status, deleted, create_time, update_time FROM rbac_role WHERE account_id = #{accountId} AND deleted = 0
AND role_code LIKE CONCAT('%', #{roleCode}, '%')
AND role_name LIKE CONCAT('%', #{roleName}, '%')
AND status = #{status}
ORDER BY id DESC LIMIT #{offset}, #{pageSize}
